// --- Review cases (PR-05B) ----------------------------------------------

export type ReviewStatus =
  | "not_reviewed"
  | "under_review"
  | "explained_deviation"
  | "needs_source_verification"
  | "escalated_for_examination";

export type CaseEventType =
  | "created"
  | "note_added"
  | "status_changed"
  | "decision_recorded"
  | "reopened";

/** Alias matching the OpenAPI schema name (EventType). */
export type EventType = CaseEventType;

export interface CreateCaseRequest {
  dataset_id: string;
  snapshot_id: string;
  record_ref: string;
  title: string;
  summary?: string | null;
  /** Ignored by the server — actor is derived from the authenticated principal. */
  created_by: string;
}

export interface CaseSummary {
  id: string;
  dataset_id: string;
  snapshot_id: string;
  record_ref: string;
  status: ReviewStatus;
  title: string;
  summary?: string | null;
  created_at: string;
  updated_at: string;
  version: number;
  created_by: string;
}

export type CaseDetail = CaseSummary;

export interface CaseListResponse {
  items: CaseSummary[];
  total: number;
  limit: number;
  offset: number;
}

export interface AddNoteRequest {
  note_text: string;
  /** Ignored by the server — actor is derived from the authenticated principal. */
  actor_ref: string;
  expected_version: number;
}

export interface TransitionStatusRequest {
  to_status: ReviewStatus;
  reason: string;
  /** Ignored by the server — actor is derived from the authenticated principal. */
  actor_ref: string;
  expected_version: number;
}

export interface RecordDecisionRequest {
  outcome: ReviewStatus;
  rationale: string;
  /** Ignored by the server — actor is derived from the authenticated principal. */
  actor_ref: string;
  expected_version: number;
}

export interface CaseEventRecord {
  id: string;
  case_id: string;
  event_type: CaseEventType;
  event_at: string;
  actor_ref: string;
  previous_status?: ReviewStatus | null;
  new_status?: ReviewStatus | null;
  reason?: string | null;
  event_payload?: Record<string, unknown> | null;
  case_version: number;
  event_seq: number;
}

export interface CaseHistoryResponse {
  case_id: string;
  items: CaseEventRecord[];
  total: number;
}

// --- Research (PR-08: read-only frozen scientific results) --------------

export interface ResearchSourceSummary {
  source_id: string;
  dataset_id: string;
  research_family: string;
  model_methods: string[];
  result_type: string;
  result_granularity: string;
  availability: string;
}

export interface ResearchSourceListResponse {
  items: ResearchSourceSummary[];
  count: number;
}

export interface ResearchSourceDetail extends ResearchSourceSummary {
  artifact_path: string;
  artifact_sha256: string;
  digest_algorithm: string;
  canonicalization: string;
  experimental_context: Record<string, unknown>;
  limitations: string[];
}

export interface ResearchResultItem {
  metric_name: string;
  value: number | string;
  value_type: "int" | "float" | "str";
  description: string;
}

export interface ResearchProvenance {
  artifact_path: string;
  artifact_sha256: string;
  digest_algorithm: string;
  canonicalization: string;
}

export interface ResearchResultsResponse {
  source_id: string;
  dataset_id: string;
  model_methods: string[];
  results: ResearchResultItem[];
  interpretation_principles: string[];
  exploratory_caveat: string;
  provenance: ResearchProvenance;
  limitations: string[];
  is_precomputed: true;
  is_live_prediction: false;
}

// --- Benchmark (PR-09: canonical ten-run IF/LOF benchmark) --------------

/** Identity of one consumed frozen artifact. */
export interface ArtifactProvenance {
  path: string;
  sha256: string;
  digest_algorithm: "sha-256";
  canonicalization: string;
}

/** Provenance of a run's parameter configuration. */
export interface ParameterSourceProvenance extends ArtifactProvenance {
  note: string;
}

/** One canonical benchmark run in the list view. */
export interface BenchmarkExperimentSummary {
  run_id: string;
  algorithm: "IsolationForest" | "LOF";
  parameters: Record<string, unknown>;
  parameter_source: ParameterSourceProvenance;
  dataset_id: string;
  model_status: "fitted_offline_frozen";
  metrics_available: boolean;
  row_lookup_available: boolean;
}

/** Per-capability availability of a DVC-backed evidence layer. */
export interface BenchmarkCapabilityStatus {
  available: boolean;
  reason: "artifact_missing" | "integrity_failed" | null;
  detail: string | null;
}

/** The verified ten-run benchmark catalog. */
export interface BenchmarkCatalogResponse {
  source_id: string;
  dataset_id: string;
  experiments: BenchmarkExperimentSummary[];
  count: number;
  capabilities: Record<string, BenchmarkCapabilityStatus>;
  limitations: string[];
}

/** Frozen dataset and experiment context of the canonical benchmark. */
export interface DatasetScope {
  sample: Record<string, unknown>;
  registry_summary: Record<string, unknown>;
  threshold_rule: string;
  threshold_percentile: number;
  sample_seed: number;
  score_orientation: Record<string, unknown>;
  environment: Record<string, unknown>;
  model_fitting: Record<string, unknown>;
}

/** Full descriptor of one canonical benchmark run. */
export interface BenchmarkExperimentDetail {
  run_id: string;
  algorithm: "IsolationForest" | "LOF";
  parameters: Record<string, unknown>;
  fixed_pipeline_settings: Record<string, unknown>;
  parameter_source: ParameterSourceProvenance;
  dataset_id: string;
  model_status: "fitted_offline_frozen";
  metrics_available: boolean;
  row_lookup_available: boolean;
  dataset_scope: DatasetScope;
  provenance: Record<string, ArtifactProvenance>;
  limitations: string[];
}

/** Definition and denominator semantics of one saved metric. */
export interface BenchmarkMetricDefinition {
  metric_name: string;
  definition: string;
  denominator: string;
}

/** Saved Phase 4 metrics of one canonical run, exactly as admitted. */
export interface BenchmarkRunMetrics {
  run_id: string;
  model: string;
  average_precision: number;
  roc_auc: number;
  precision_at_1pct: number;
  recall_at_1pct: number;
  f1_at_1pct: number;
  tn: number;
  fp: number;
  fn: number;
  tp: number;
  sample_size: number;
  fraud_count: number;
  fraud_prevalence: number;
  flagged_count: number;
  flagged_proportion: number;
  runtime_seconds: number | null;
  threshold_rule: string;
}

/** Verified saved metrics for the canonical ten-run benchmark. */
export interface BenchmarkMetricsResponse {
  source_id: string;
  dataset_id: string;
  sample: Record<string, unknown>;
  metrics: BenchmarkRunMetrics[];
  metric_definitions: BenchmarkMetricDefinition[];
  provenance: Record<string, unknown>;
  limitations: string[];
  is_precomputed: true;
  is_live_prediction: false;
}

/** Ground-truth label block of a canonical record. */
export interface RecordLabelBlock {
  Class: number;
  provenance: string;
}

/** Saved scores of a canonical record. */
export interface RecordScoreBlock {
  native_score: number;
  anomaly_score: number;
  native_definition: string;
  anomaly_definition: string;
}

/** Saved detector flag of a canonical record. */
export interface RecordFlagBlock {
  value: number;
  provenance: string;
}

/** One canonical record, resolved by exact saved row_id. */
export interface BenchmarkRecordResponse {
  run_id: string;
  row_id: number;
  label: RecordLabelBlock;
  scores: RecordScoreBlock;
  flag: RecordFlagBlock;
  dataset_id: string;
  sample: Record<string, unknown>;
  score_orientation: Record<string, unknown>;
  provenance: Record<string, unknown>;
  limitations: string[];
  is_precomputed: true;
  is_live_prediction: false;
}
